insert into public.exercises(id,slug,title,category,difficulty,description,instructions,common_mistakes,warnings,reps,seconds,rest_seconds,easier,harder,equipment,media_url,active) values('cede21ad-6937-5381-8ffc-78e43f4e86cc','march','Шаги на месте','activity','beginner','Мягко переносите вес с ноги на ногу.','["Встаньте рядом с опорой", "Поднимайте стопы невысоко", "Не задерживайте дыхание"]'::jsonb,'Рывки, чрезмерная амплитуда, задержка дыхания.','При боли, головокружении или недомогании остановитесь. При ограничениях обсудите движение со специалистом.',6,40,20,'Держаться за спинку стула','Добавить спокойные движения рук','["none"]'::jsonb,null,true) on conflict (id) do nothing;
insert into public.exercises(id,slug,title,category,difficulty,description,instructions,common_mistakes,warnings,reps,seconds,rest_seconds,easier,harder,equipment,media_url,active) values('6c09849b-427e-5837-a4bb-7abfb27ed2ab','wall-push','Отжимание от стены','activity','beginner','Нагрузка регулируется расстоянием от стены.','["Ладони на стене на уровне груди", "Согните локти без провала поясницы", "Плавно оттолкнитесь"]'::jsonb,'Рывки, чрезмерная амплитуда, задержка дыхания.','При боли, головокружении или недомогании остановитесь. При ограничениях обсудите движение со специалистом.',6,40,20,'Подойти ближе к стене','Отойти на небольшой шаг','["none"]'::jsonb,null,true) on conflict (id) do nothing;
insert into public.exercises(id,slug,title,category,difficulty,description,instructions,common_mistakes,warnings,reps,seconds,rest_seconds,easier,harder,equipment,media_url,active) values('7589808e-0d7f-5cb0-bfee-833c723ad976','heel-raise','Подъём на носки','activity','beginner','Работайте рядом с устойчивой опорой.','["Держитесь за опору", "Плавно приподнимите пятки", "Медленно опустите"]'::jsonb,'Рывки, чрезмерная амплитуда, задержка дыхания.','При боли, головокружении или недомогании остановитесь. При ограничениях обсудите движение со специалистом.',6,40,20,'Небольшая амплитуда','Короткая пауза вверху','["none"]'::jsonb,null,true) on conflict (id) do nothing;
insert into public.exercises(id,slug,title,category,difficulty,description,instructions,common_mistakes,warnings,reps,seconds,rest_seconds,easier,harder,equipment,media_url,active) values('39c03810-ed7c-5ebb-98be-bf85cba7ad23','side-step','Шаг в сторону','activity','beginner','Короткие шаги без прыжков.','["Слегка согните колени", "Шагните в сторону и приставьте ногу", "Повторите в другую сторону"]'::jsonb,'Рывки, чрезмерная амплитуда, задержка дыхания.','При боли, головокружении или недомогании остановитесь. При ограничениях обсудите движение со специалистом.',6,40,20,'Уменьшить шаг','Сделать ещё два шага','["none"]'::jsonb,null,true) on conflict (id) do nothing;
insert into public.exercises(id,slug,title,category,difficulty,description,instructions,common_mistakes,warnings,reps,seconds,rest_seconds,easier,harder,equipment,media_url,active) values('db260720-1d76-50d7-9e18-8607d29db404','hip-hinge','Наклон от таза','activity','beginner','Учимся двигаться от тазобедренных суставов.','["Колени мягкие", "Отведите таз назад с ровной спиной", "Вернитесь без рывка"]'::jsonb,'Рывки, чрезмерная амплитуда, задержка дыхания.','При боли, головокружении или недомогании остановитесь. При ограничениях обсудите движение со специалистом.',6,40,20,'Опираться руками на бёдра','Чуть увеличить амплитуду','["none"]'::jsonb,null,true) on conflict (id) do nothing;
insert into public.exercises(id,slug,title,category,difficulty,description,instructions,common_mistakes,warnings,reps,seconds,rest_seconds,easier,harder,equipment,media_url,active) values('11acc66c-dafe-5671-8e84-4f2e30dd5374','bridge','Ягодичный мост','activity','beginner','Небольшой подъём таза лёжа.','["Лягте на спину и согните колени", "Поднимите таз без прогиба", "Плавно опустите"]'::jsonb,'Рывки, чрезмерная амплитуда, задержка дыхания.','При боли, головокружении или недомогании остановитесь. При ограничениях обсудите движение со специалистом.',6,40,20,'Поднять таз совсем немного','Удержать верхнюю точку на один выдох','["none"]'::jsonb,null,true) on conflict (id) do nothing;
insert into public.exercises(id,slug,title,category,difficulty,description,instructions,common_mistakes,warnings,reps,seconds,rest_seconds,easier,harder,equipment,media_url,active) values('cf882071-612b-572b-8616-c268df7d2edd','bird-dog','Баланс на четвереньках','activity','beginner','Не стремитесь поднять конечности высоко.','["Встаньте на четвереньки", "Вытяните одну руку или ногу", "Верните и смените сторону"]'::jsonb,'Рывки, чрезмерная амплитуда, задержка дыхания.','При боли, головокружении или недомогании остановитесь. При ограничениях обсудите движение со специалистом.',6,40,20,'Только скользить ногой по полу','Вытянуть противоположные руку и ногу','["none"]'::jsonb,null,true) on conflict (id) do nothing;
insert into public.exercises(id,slug,title,category,difficulty,description,instructions,common_mistakes,warnings,reps,seconds,rest_seconds,easier,harder,equipment,media_url,active) values('2daa1276-3da5-56e8-9874-45ea352eab65','squat','Приседания','activity','beginner','6–10 спокойных приседаний за подход; глубина комфортная.','["Стопы примерно на ширине плеч, вес на всей стопе.", "Отведите таз назад и согните колени по направлению носков.", "Опуститесь до комфортной глубины, затем выпрямитесь на выдохе."]'::jsonb,'Рывки, задержка дыхания, потеря устойчивого положения корпуса.','При боли, головокружении или недомогании остановитесь. При ограничениях обсудите движение со специалистом.',8,30,30,'Неглубокие приседания с опорой рукой о стену.','10–12 повторов с медленным опусканием.','["none"]'::jsonb,null,true) on conflict do nothing;
insert into public.exercises(id,slug,title,category,difficulty,description,instructions,common_mistakes,warnings,reps,seconds,rest_seconds,easier,harder,equipment,media_url,active) values('f87d837d-5cad-51af-9c57-148f9822380b','knee-push','Отжимания с колен','activity','intermediate','6–10 контролируемых отжиманий; закончите подход раньше, если теряется техника.','["Встаньте в упор на ладонях и коленях; подложите мягкую нескользящую поверхность.", "Сохраните прямую линию от коленей до головы, напрягите живот.", "Согните локти под углом около 45° к корпусу, опустите грудь и оттолкнитесь на выдохе."]'::jsonb,'Рывки, задержка дыхания, потеря устойчивого положения корпуса.','При боли, головокружении или недомогании остановитесь. При ограничениях обсудите движение со специалистом.',8,30,30,'Отжимания от стены.','Отжимания с опорой на стопы по 5–8 повторов.','["none"]'::jsonb,null,true) on conflict do nothing;
insert into public.exercises(id,slug,title,category,difficulty,description,instructions,common_mistakes,warnings,reps,seconds,rest_seconds,easier,harder,equipment,media_url,active) values('310ff74d-e47b-5058-a176-286183896be4','reverse-lunge','Выпады назад','activity','intermediate','По 5–8 выпадов на каждую сторону; без спешки.','["Встаньте ровно, при необходимости держитесь за стену.", "Шагните назад и согните оба колена до комфортной глубины.", "Вернитесь через переднюю стопу и смените сторону."]'::jsonb,'Рывки, задержка дыхания, потеря устойчивого положения корпуса.','При боли, головокружении или недомогании остановитесь. При ограничениях обсудите движение со специалистом.',8,30,30,'Неглубокий выпад с опорой или обычные приседания.','Чуть более медленное опускание, без дополнительного веса.','["none"]'::jsonb,null,true) on conflict do nothing;
